// Idioma: el primero de los preferidos del iPhone/navegador que tengamos; si no, español.
// Se puede elegir a mano en Info. Para probar: añade ?lang=en (o fr, pt, de, zh, hi, ar, bn, ru, ja) a la dirección.
// Nombre de cada idioma en su propio idioma (para el selector de Info)
const LANG_NAMES = { es: "Español", en: "English", fr: "Français", pt: "Português", de: "Deutsch", zh: "中文（简体）", hi: "हिन्दी", ar: "العربية", bn: "বাংলা", ru: "Русский", ja: "日本語" };
// Idioma elegido a mano en Info ("" = automático)
const LANG_CHOICE = (() => { try { const v = JSON.parse(localStorage.getItem("lang") || '""'); return LANGS.includes(v) ? v : ""; } catch { return ""; } })();
const LANG = (() => {
  try {
    const forced = new URLSearchParams(location.search).get("lang");
    if (forced && LANGS.includes(forced)) return forced;
  } catch {}
  if (LANG_CHOICE) return LANG_CHOICE;
  const prefs = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || ""]);
  for (const l of prefs) {
    const p = String(l).toLowerCase().split(/[-_]/)[0];
    if (LANGS.includes(p)) return p;
  }
  return "es";
})();
// Formato de fechas y números: el del idioma elegido (respetando la región del iPhone si coincide)
const LOCALE = (() => {
  const def = { es: "es-ES", en: "en-US", fr: "fr-FR", pt: "pt-BR", de: "de-DE", zh: "zh-CN", hi: "hi-IN", ar: "ar", bn: "bn-BD", ru: "ru-RU", ja: "ja-JP" }[LANG];
  let loc = def;
  for (const l of navigator.languages || []) {
    if (String(l).toLowerCase().split(/[-_]/)[0] === LANG) { loc = String(l); break; }
  }
  // Árabe y bengalí con cifras 0-9, como el resto de la interfaz
  if (LANG === "ar" || LANG === "bn") loc += "-u-nu-latn";
  try { new Intl.DateTimeFormat(loc); return loc; } catch { return def; }
})();
const I18N = (() => {
  const d = {};
  const j = ["ru", "ja"].indexOf(LANG);
  if (j >= 0) { for (const r of I18N_RU_JA) if (r[j + 1]) d[r[0]] = r[j + 1]; return d; }
  const i = LANGS.indexOf(LANG);
  if (i > 0) for (const r of I18N_ROWS) if (r[i]) d[r[0]] = r[i];
  return d;
})();
function t(s, ...a) {
  const r = I18N[s] || s;
  return a.length ? r.replace(/\{(\d)\}/g, (m, n) => (a[n] != null ? a[n] : m)) : r;
}
// Traduce la página: data-i18n (texto), data-i18n-ph (placeholder), data-i18n-aria, data-i18n-title.
// Si el atributo va vacío, la clave es el propio texto en español.
// data-i18n-html: texto con elementos dentro ({0}, {1}… son esos elementos, en orden).
function applyI18n() {
  const html = document.documentElement;
  html.lang = LANG;
  html.dir = LANG === "ar" ? "rtl" : "ltr";
  document.querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = t(el.dataset.i18n || el.textContent.trim()); });
  document.querySelectorAll("[data-i18n-ph]").forEach((el) => { el.placeholder = t(el.dataset.i18nPh || el.placeholder); });
  document.querySelectorAll("[data-i18n-aria]").forEach((el) => { el.setAttribute("aria-label", t(el.dataset.i18nAria || el.getAttribute("aria-label"))); });
  document.querySelectorAll("[data-i18n-title]").forEach((el) => { el.title = t(el.dataset.i18nTitle || el.title); });
  document.querySelectorAll("[data-i18n-html]").forEach((el) => {
    const kids = [...el.children];
    const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    el.innerHTML = esc(t(el.dataset.i18nHtml)).replace(/\{(\d)\}/g, (m, n) => (kids[n] ? kids[n].outerHTML : m));
  });
}
applyI18n();
